{
  "$schema": "https://opencode.ai/config.json",
  "instructions": ["AGENTS.md", "CONTRIBUTING.md"]
}

{
  "name": "opencode-lookout",
  "version": "0.1.3",
  "description": "A native-style resource sidebar for OpenCode, with reversible local controls.",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "tui",
    "terminal",
    "sidebar",
    "developer-tools"
  ],
  "author": "Justin Soderberg (sodejm)",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/sodejm/opencode-lookout.git"
  },
  "bugs": {
    "url": "https://github.com/sodejm/opencode-lookout/issues"
  },
  "homepage": "https://github.com/sodejm/opencode-lookout#readme",
  "engines": {
    "node": ">=22"
  },
  "publishConfig": {
    "access": "public",
    "registry": "https://registry.npmjs.org/"
  },
  "files": [
    "src/",
    "bin/lookout.mjs",
    "dist/tui.js",
    "docs/*.md",
    "CHANGELOG.md",
    "SECURITY.md",
    "SUPPORT.md",
    "CONTRIBUTING.md",
    "GOVERNANCE.md",
    "CODE_OF_CONDUCT.md"
  ],
  "bin": {
    "lookout": "bin/lookout.mjs"
  },
  "type": "module",
  "exports": {
    ".": "./src/server.ts",
    "./tui": "./dist/tui.js",
    "./rpc": "./src/rpc.ts"
  },
  "scripts": {
    "build": "node scripts/build-tui.mjs --write",
    "build:check": "node scripts/build-tui.mjs",
    "test": "node --test test/*.test.mjs",
    "test:package": "node test/packed.mjs",
    "typecheck": "tsc --noEmit",
    "lint": "eslint . --max-warnings 0",
    "test:compatibility": "node scripts/compatibility.mjs",
    "security": "node scripts/security.mjs",
    "release:check": "node scripts/release-check.mjs",
    "format:check": "prettier --check 'src/**/*.{mjs,ts,tsx}' 'test/**/*.mjs' 'bin/*.mjs' 'scripts/*.mjs' '*.json' '.github/**/*.yml' '.vscode/*.json' 'eslint.config.mjs' 'opencode-lookout.code-workspace'",
    "test:integration": "node test/integration.mjs",
    "test:tui": "LOOKOUT_TUI=1 node test/integration.mjs",
    "docs:check": "node scripts/check-docs.mjs",
    "check": "npm run format:check && npm run docs:check && npm run lint && npm run typecheck && npm run build:check && npm test && npm run test:package"
  },
  "dependencies": {
    "jsonc-parser": "3.3.1"
  },
  "peerDependencies": {
    "@opencode/plugin": ">=2.2.1 <=2.2.6",
    "@opentui/core": "^0.8.0",
    "@opentui/solid": "^0.8.0",
    "solid-js": "^1.9.0"
  },
  "peerDependenciesMeta": {
    "@opencode/plugin": {
      "optional": true
    },
    "@opentui/core": {
      "optional": true
    },
    "@opentui/solid": {
      "optional": true
    },
    "solid-js": {
      "optional": true
    }
  },
  "overrides": {
    "glob@>=9 <=14.0.1": "14.0.3",
    "minimatch@>=7 <11.0.1": "11.0.4"
  },
  "devDependencies": {
    "@babel/core": "7.29.7",
    "@babel/preset-typescript": "7.27.1",
    "@types/babel__core": "7.20.5",
    "babel-preset-solid": "1.9.16",
    "@eslint/js": "10.0.1",
    "@opencode/client": "2.2.5",
    "@opencode/plugin": "2.2.5",
    "@opencode/theme": "2.2.5",
    "@opentui/core": "0.8.0",
    "@opentui/solid": "0.8.0",
    "@types/node": "26.6.6",
    "eslint": "10.14.0",
    "eslint-plugin-jsdoc": "65.4.3",
    "globals": "17.14.0",
    "prettier": "3.9.10",
    "solid-js": "1.9.16",
    "typescript": "5.9.3",
    "typescript-eslint": "8.72.1"
  }
}
